query GetAgentOrgDefinitions {
  agentOrgDefinitions {
    id
    name
    description
    instructions
    category
    avatarUrl
    revision
    handoffs {
      from
      to
      rules
      __typename
    }
    members {
      memberName
      ref
      refType
      refScope
      __typename
    }
    defaultLaunchConfig {
      llmModelIdentifier
      runtimeKind
      llmConfig
      __typename
    }
    __typename
  }
}

query GetAgentOrgReferencedAgent($id: String!) {
  agentDefinition(id: $id) {
    id
    name
    description
    ownershipScope
    ownerOrgId
    ownerTeamId
    __typename
  }
}

